import{_ as a,o as s,c as e,ag as r,j as o}from"./chunks/framework.KxDd3USm.js";const y=JSON.parse('{"title":"03.9 案例题专攻：数据流图","description":"","frontmatter":{},"headers":[],"relativePath":"03-软件工程基础/09-案例题专攻.md","filePath":"03-软件工程基础/09-案例题专攻.md"}'),d={name:"03-软件工程基础/09-案例题专攻.md"},n={class:"fig"},l={"data-figure-id":"figure-22",viewBox:"0 0 760 390",width:"100%",style:{"max-width":"760px"},role:"img","aria-label":"数据流图父子图平衡示意。左侧父图中，顾客向订单处理系统输入订单，系统向顾客输出订单确认，向餐厅输出订单信息。右侧零层图把订单处理系统分成接收订单和分派订单两个加工，并加入订单文件；系统对外的三条数据流名称和方向与父图完全相同，因此父子图平衡。订单文件及其两条内部数据流不必出现在父图。"},g={class:"fig"},x={"data-figure-id":"figure-23",viewBox:"0 0 760 248",width:"100%",style:{"max-width":"760px"},role:"img","aria-label":"数据流图三种加工错误对照。黑洞加工只有订单输入没有输出；奇迹加工只有订单确认输出没有输入；灰洞加工只有还书请求输入却输出还书结果和更新后的在馆状态，缺少读取图书文件中在馆状态的输入。"};function u(h,t,i,c,q,p){return s(),e("div",null,[t[4]||(t[4]=r('<h1 id="_03-9-案例题专攻-数据流图" tabindex="-1">03.9 案例题专攻：数据流图 <a class="header-anchor" href="#_03-9-案例题专攻-数据流图" aria-label="Permalink to &quot;03.9 案例题专攻：数据流图&quot;">​</a></h1><p>案例第一题一般是「文字说明 + 顶层图或 0 层图（缺数据流）」，固定三小问：补数据流、补数据存储或补外部实体、补数据字典。<strong>全部答案都藏在说明文字里</strong>，套路如下。</p><h3 id="_9-0-先认全-dfd-的四种元素-认不出元素就找不到答案" tabindex="-1">9.0 先认全 DFD 的四种元素（认不出元素就找不到答案） <a class="header-anchor" href="#_9-0-先认全-dfd-的四种元素-认不出元素就找不到答案" aria-label="Permalink to &quot;9.0 先认全 DFD 的四种元素（认不出元素就找不到答案）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>元素</th><th>常见画法</th><th>表示什么</th><th>命名规则</th></tr></thead><tbody><tr><td><strong>外部实体</strong></td><td>矩形</td><td>系统之外的<strong>人、组织、外部系统</strong>（顾客、餐厅、银行、支付网关）</td><td>名词（&quot;读者&quot;&quot;支付网关&quot;）</td></tr><tr><td><strong>加工</strong></td><td>圆角矩形 / 圆圈</td><td>对数据做的<strong>变换</strong>（计算、校验、存库）</td><td><strong>动词 + 名词</strong>（&quot;接收订单&quot;&quot;校验资格&quot;）</td></tr><tr><td><strong>数据存储</strong></td><td>开口矩形 / 双平行线</td><td><strong>文件、表、库、清单</strong></td><td>名词 + 类型（&quot;订单文件&quot;&quot;库存表&quot;）</td></tr><tr><td><strong>数据流</strong></td><td>带名字的箭头</td><td>数据的流动方向</td><td>名词（&quot;订单&quot;&quot;待处理订单&quot;）</td></tr></tbody></table><p><strong>两条画法铁律（真题的判错依据）</strong>：</p><ol><li><strong>数据存储不能直接连外部实体</strong>。外部实体要读文件，必须通过某个加工中转——例如「配送员从配送文件取餐通知」，正确画法是 <strong>配送文件 →(配送任务)→ 加工 →(取餐通知)→ 配送员</strong>，绝不能画成「配送文件 → 配送员」。</li><li><strong>DFD 不画控制流</strong>。像&quot;先判断是否逾期，再决定是否拒绝&quot;这种逻辑，DFD 里只体现为<strong>数据</strong>的走向（多了/少了哪条流），不画带条件标注的控制箭头。</li></ol><h3 id="_9-1-套路一-分层与平衡原则-判断-缺什么-的唯一依据" tabindex="-1">9.1 套路一：分层与平衡原则（判断&quot;缺什么&quot;的唯一依据） <a class="header-anchor" href="#_9-1-套路一-分层与平衡原则-判断-缺什么-的唯一依据" aria-label="Permalink to &quot;9.1 套路一：分层与平衡原则（判断&quot;缺什么&quot;的唯一依据）&quot;">​</a></h3><ul><li><strong>顶层图</strong>：整个系统算<strong>一个</strong>加工，只画外部实体和进出系统的数据流，不画数据存储；</li><li><strong>0 层图</strong>：把系统拆成几个主要加工，画出外部实体、加工、数据存储、数据流；</li><li><strong>父子图必须平衡</strong>：子图的输入/输出数据流，必须与父图中对应加工的输入/输出<strong>一一对应</strong>。父子图对不上 = 缺流，这就是补流题的判定依据。</li></ul>',8)),o("figure",n,[(s(),e("svg",l,[...t[0]||(t[0]=[r('<defs><marker id="dfd-arrow" markerWidth="8" markerHeight="8" refX="7" refY="4" orient="auto"><path d="M0,0 L8,4 L0,8z" fill="var(--ink)"></path></marker></defs><text x="150" y="26" class="head">父图：顶层图</text><text x="530" y="26" class="head">子图：0 层图</text><rect x="18" y="55" width="300" height="285" rx="10" class="dash"></rect><text x="105" y="78" class="small">父图示意区</text><rect x="34" y="170" width="70" height="42" rx="3" class="box"></rect><text x="55" y="196" class="t">顾客</text><rect x="230" y="170" width="70" height="42" rx="3" class="box"></rect><text x="251" y="196" class="t">餐厅</text><rect x="124" y="147" width="88" height="88" rx="44" class="proc"></rect><text x="143" y="187" class="t">订单处理</text><text x="157" y="205" class="t">系统</text><path d="M104 181H123" class="edge" marker-end="url(#dfd-arrow)"></path><text x="105" y="166" class="small">订单</text><path d="M212 181H229" class="edge" marker-end="url(#dfd-arrow)"></path><text x="211" y="166" class="small">订单信息</text><path d="M168 235V280H68V213" class="edge" marker-end="url(#dfd-arrow)"></path><text x="86" y="298" class="small">订单确认</text><text x="368" y="196" class="small">拆分</text><path d="M330 190H406" class="edge" marker-end="url(#dfd-arrow)"></path><rect x="430" y="55" width="312" height="285" rx="10" class="dash"></rect><text x="525" y="78" class="small">子图示意区</text><rect x="446" y="170" width="58" height="42" rx="3" class="box"></rect><text x="459" y="196" class="t">顾客</text><rect x="678" y="170" width="48" height="42" rx="3" class="box"></rect><text x="686" y="196" class="t">餐厅</text><rect x="530" y="105" width="90" height="48" rx="24" class="proc"></rect><text x="545" y="134" class="t">接收订单</text><rect x="530" y="235" width="90" height="48" rx="24" class="proc"></rect><text x="545" y="264" class="t">分派订单</text><path d="M504 181H529V153" class="edge" marker-end="url(#dfd-arrow)"></path><text x="505" y="166" class="small">订单</text><path d="M575 153V234" class="edge" marker-end="url(#dfd-arrow)"></path><text x="585" y="202" class="small">待处理订单</text><path d="M620 259H677" class="edge" marker-end="url(#dfd-arrow)"></path><text x="624" y="245" class="small">订单信息</text><path d="M530 129H480V213" class="edge" marker-end="url(#dfd-arrow)"></path><text x="445" y="236" class="small">订单确认</text><path d="M620 129H655V97H627" class="edge" marker-end="url(#dfd-arrow)"></path><path d="M627 110H655" class="edge"></path><text x="657" y="108" class="small">订单文件</text><text x="26" y="372" class="small">核对口诀：系统对外的流必须相同；子图新增的加工、数据存储和内部流不要求出现在父图。</text>',42)])])),t[1]||(t[1]=o("figcaption",null,"父子图平衡：核对的是穿过对应加工或系统边界的输入、输出流，不是逐一照搬内部加工和文件。",-1))]),t[5]||(t[5]=r(`<h3 id="_9-2-套路二-逐句扫描说明找缺失数据流" tabindex="-1">9.2 套路二：逐句扫描说明找缺失数据流 <a class="header-anchor" href="#_9-2-套路二-逐句扫描说明找缺失数据流" aria-label="Permalink to &quot;9.2 套路二：逐句扫描说明找缺失数据流&quot;">​</a></h3><p>说明里<strong>每个动词句都对应一条数据流</strong>（有些句子对应两条，见下）。做法是把它变成对账：</p><p><strong>第一步，把说明拆成&quot;起点 → 终点 → 名字&quot;的三元组</strong>。以&quot;系统按订单文件中的待处理订单，向相应餐厅发送订单信息&quot;这一句为例，它藏着<strong>两个</strong>动作：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>动作①  读文件：  订单文件  →（待处理订单）→ 加工②      ← 文件流向加工（读）</span></span>
<span class="line"><span>动作②  发出去：  加工②    →（订单信息）  → 餐厅        ← 加工流向外部实体</span></span></code></pre></div><p><strong>一句话对应两条流</strong>，是补流题最容易漏的地方——别以为一句只找一条。</p><p><strong>第二步，把三元组清单和图上已有的箭头逐条对账</strong>，图上找不到的，就是答案。</p><p><strong>第三步，名字用说明原词</strong>。题目通常明确要求&quot;采用说明中的词汇&quot;，说明写&quot;订单信息&quot;就照抄，不要改写成&quot;订单数据&quot;。</p><h3 id="_9-3-套路三-补流三要素与三类最易漏的流" tabindex="-1">9.3 套路三：补流三要素与三类最易漏的流 <a class="header-anchor" href="#_9-3-套路三-补流三要素与三类最易漏的流" aria-label="Permalink to &quot;9.3 套路三：补流三要素与三类最易漏的流&quot;">​</a></h3><p><strong>答案必须写全三要素：起点、终点、数据流名</strong>——只写名字不给起终点，阅卷时按半分处理。</p><p>真题里最常漏的就是这三类：</p><table tabindex="0"><thead><tr><th>类型</th><th>例子</th><th>为什么容易漏</th></tr></thead><tbody><tr><td><strong>加工 → 外部实体的反馈类流</strong></td><td>订单确认、送达通知、拒绝提示</td><td>说明里写成&quot;系统向××发送…&quot;，容易被当成一句套话跳过</td></tr><tr><td><strong>加工 ↔ 数据存储的读流</strong></td><td>订单文件→加工（待处理订单）</td><td>只记得&quot;存文件&quot;是流，忘了<strong>读文件同样是流</strong></td></tr><tr><td><strong>顶层有而 0 层没有的流</strong></td><td>顶层图里的&quot;订单信息→餐厅&quot;</td><td>只盯着 0 层图看，没回头和顶层图对照</td></tr></tbody></table><p><strong>自查动作（做完必做）</strong>：图上<strong>每个加工都必须既有进入的流、又有出去的流</strong>。发现有&quot;只进不出&quot;或&quot;只出不进&quot;的加工，那里一定缺流（原理见 9.7）。</p><h3 id="_9-4-套路四-补外部实体" tabindex="-1">9.4 套路四：补外部实体 <a class="header-anchor" href="#_9-4-套路四-补外部实体" aria-label="Permalink to &quot;9.4 套路四：补外部实体&quot;">​</a></h3><p><strong>判据一：说明里出现在&quot;向××提交/发送/通知&quot;或&quot;由××提供&quot;位置的、系统以外的人或组织。</strong></p><ul><li>是外部实体：<strong>人</strong>（顾客、读者、管理员）、<strong>组织</strong>（餐厅、供应商、银行）、<strong>外部系统</strong>（支付网关、短信平台、身份认证服务）；</li><li>不是外部实体：说明里的&quot;<strong>系统</strong>&quot;&quot;平台&quot;指的是<strong>正在建模的系统自身</strong>，它是加工不是实体；数据库、文件是数据存储也不是实体。</li></ul><p><strong>判据二：数一数说明里出现过的角色</strong>。真题常让你&quot;补出图中的外部实体&quot;，答案个数就等于说明里出现的外部角色个数——漏一个通常是因为某句里角色只当宾语出现一次（如&quot;系统向<strong>顾客</strong>发送送达通知&quot;）。</p><p><strong>反例</strong>：说明写&quot;系统生成配送任务写入配送文件&quot;，若把&quot;系统&quot;填成外部实体即错——它是 0 层图的整体，被拆成了各加工。</p><h3 id="_9-5-套路五-补数据存储-文件名" tabindex="-1">9.5 套路五：补数据存储（文件名） <a class="header-anchor" href="#_9-5-套路五-补数据存储-文件名" aria-label="Permalink to &quot;9.5 套路五：补数据存储（文件名）&quot;">​</a></h3><p><strong>判据：说明里的名词中含&quot;文件 / 表 / 库 / 清单 / 档案 / 日志 / 台账&quot;这类词，且数据需要被保存下来。</strong></p><ul><li>例：订单文件、配送文件、图书文件、读者文件、借阅记录表、库存清单；</li><li><strong>反例（高频错）</strong>：题目让填&quot;数据存储&quot;时，把&quot;订单&quot;填进去——&quot;订单&quot;是<strong>数据流名</strong>，&quot;订单文件&quot;才是存储名。<strong>数据是内容、文件是容器</strong>，别混。</li><li><strong>方向也要判</strong>：谁写（加工 → 文件）、谁读（文件 → 加工）。<strong>一个文件通常既有入流也有出流</strong>；只画了写没画读，就是漏流。</li></ul><h3 id="_9-6-套路六-补加工名" tabindex="-1">9.6 套路六：补加工名 <a class="header-anchor" href="#_9-6-套路六-补加工名" aria-label="Permalink to &quot;9.6 套路六：补加工名&quot;">​</a></h3><p>加工名 = <strong>动词 + 名词</strong>，通常 2–6 个字，且必须与图上箭头吻合。三步定名：</p><p><strong>第一步，看这个加工有哪些输入流、哪些输出流</strong>（箭头就是线索）； <strong>第二步，回说明里找&quot;用这些输入产生这些输出&quot;的那句话</strong>； <strong>第三步，用说明里的动词短语命名</strong>（&quot;接收订单&quot;&quot;分派订单&quot;&quot;跟踪配送&quot;&quot;处理还书&quot;）。</p><p><strong>反例</strong>：把加工名写成&quot;处理&quot;（太笼统）、&quot;订单&quot;（纯名词）、&quot;系统&quot;（不是加工名）、&quot;接收订单并分派订单并跟踪配送&quot;（一个加工干了三个加工的活）——四种都是错项。</p><h3 id="_9-7-dfd-的三种错误-黑洞、奇迹、灰洞-平衡的反面-选择题也考" tabindex="-1">9.7 DFD 的三种错误：黑洞、奇迹、灰洞（平衡的反面，选择题也考） <a class="header-anchor" href="#_9-7-dfd-的三种错误-黑洞、奇迹、灰洞-平衡的反面-选择题也考" aria-label="Permalink to &quot;9.7 DFD 的三种错误：黑洞、奇迹、灰洞（平衡的反面，选择题也考）&quot;">​</a></h3><p><strong>黑洞 —— 加工有输入、无输出。</strong> 成因：漏画了该加工的输出流，数据&quot;进去就没了&quot;。</p><p><strong>奇迹 —— 加工有输出、无输入。</strong> 成因：漏画了该加工的输入流，数据&quot;凭空产生&quot;。</p><p><strong>灰洞 —— 加工有输入也有输出，但输入不足以产生该输出。</strong> 成因：漏画了部分输入流，数据&quot;不够用&quot;。</p><p><strong>口诀</strong>：<strong>黑进不出、奇出不进、灰进不够出</strong>。</p>`,29)),o("figure",g,[(s(),e("svg",x,[...t[2]||(t[2]=[r('<defs><marker id="err-arrow" markerWidth="8" markerHeight="8" refX="7" refY="4" orient="auto"><path d="M0,0 L8,4 L0,8z" fill="var(--ink)"></path></marker></defs><line x1="253" y1="20" x2="253" y2="224" stroke="var(--line)"></line><line x1="507" y1="20" x2="507" y2="224" stroke="var(--line)"></line><text x="92" y="34" class="bad">黑洞</text><text x="46" y="54" class="s">有输入，没有输出</text><rect x="82" y="100" width="90" height="56" rx="28" class="p"></rect><text x="104" y="133" class="t">处理订单</text><path d="M20 128H81" class="e" marker-end="url(#err-arrow)"></path><text x="22" y="113" class="s">订单</text><text x="42" y="191" class="s">数据进去了，却没有去处</text><text x="344" y="34" class="bad">奇迹</text><text x="300" y="54" class="s">有输出，没有输入</text><rect x="336" y="100" width="90" height="56" rx="28" class="p"></rect><text x="358" y="133" class="t">处理订单</text><path d="M426 128H486" class="e" marker-end="url(#err-arrow)"></path><text x="427" y="113" class="s">订单确认</text><text x="298" y="191" class="s">没有原料，却凭空产出数据</text><text x="601" y="34" class="bad">灰洞</text><text x="554" y="54" class="s">输入不足以产生输出</text><rect x="590" y="100" width="90" height="56" rx="28" class="p"></rect><text x="612" y="133" class="t">处理还书</text><path d="M520 128H589" class="e" marker-end="url(#err-arrow)"></path><text x="520" y="113" class="s">还书请求</text><path d="M680 112H740" class="e" marker-end="url(#err-arrow)"></path><path d="M680 145H740" class="e" marker-end="url(#err-arrow)"></path><text x="680" y="101" class="s">还书结果</text><text x="650" y="166" class="s">更新后的在馆状态</text><text x="550" y="205" class="s">缺：图书文件 → 在馆状态 → 加工</text>',28)])])),t[3]||(t[3]=o("figcaption",null,"判断灰洞不能只数“有进有出”；还要追问现有输入是否足以产生每一项输出。",-1))]),t[6]||(t[6]=r('<p><strong>灰洞最难认，看例子</strong>：某&quot;处理还书&quot;的加工，只画了「管理员→（还书请求）→加工」和「加工→（还书结果）→管理员」，看起来进和出都有。但&quot;更新图书在馆状态&quot;这件事<strong>必须有图书文件里的在馆数据</strong>才能做——输入不够，输出却凭空生成了，这就是灰洞。改法：补上 图书文件 →（在馆状态）→ 加工 与 加工 →（更新后的在馆状态）→ 图书文件。</p><p><strong>应试动作</strong>：做补流题时，逐个数每个加工的进入流与流出流，三种错误当场就能查出来。</p><h3 id="_9-8-套路七-数据字典写法-五个记号背全" tabindex="-1">9.8 套路七：数据字典写法（五个记号背全） <a class="header-anchor" href="#_9-8-套路七-数据字典写法-五个记号背全" aria-label="Permalink to &quot;9.8 套路七：数据字典写法（五个记号背全）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>记号</th><th>含义</th><th>例子</th></tr></thead><tbody><tr><td><code>=</code></td><td><strong>定义</strong>为（由…组成）</td><td><code>登录信息 = 学生 ID + 密码</code></td></tr><tr><td><code>+</code></td><td><strong>与</strong>（顺序连接）</td><td><code>订单 = 顾客编号 + 菜品明细 + 送餐地址</code></td></tr><tr><td><code>{}</code></td><td><strong>重复</strong>（0 次或多次）</td><td><code>菜品明细 = {菜品名 + 数量}</code></td></tr><tr><td><code>[ | ]</code></td><td><strong>或</strong>（择一）</td><td><code>付款方式 = [现金 | 微信 | 银行卡]</code></td></tr><tr><td><code>( )</code></td><td><strong>可选</strong>（可有可无）</td><td><code>收货地址 = (省份) + 城市 + 街道</code></td></tr></tbody></table><p><strong>口诀</strong>：<strong>等号组成、加号连接、花括号重复、方括号择一、圆括号可选</strong>。</p><p><strong>反例（两个记号一换就错）</strong>：用 <code>[]</code> 表示重复、用 <code>{}</code> 表示择一——这是最典型的写法错误。判别窍门：<strong>开花（<code>{}</code>）像&quot;一串&quot;，方括号（<code>[]</code>）像&quot;岔路&quot;</strong>——重复用花、择一用方。</p><p>（说明里给出的字段名要照抄原词，字段间的连接关系按说明的语义判断：能重复多次的加 <code>{}</code>，可能没有的加 <code>()</code>。）</p><h3 id="_9-9-应试动作" tabindex="-1">9.9 应试动作 <a class="header-anchor" href="#_9-9-应试动作" aria-label="Permalink to &quot;9.9 应试动作&quot;">​</a></h3><p>① <strong>先数箭头再读说明</strong>：逐个数每个加工的进入流/流出流，抓出&quot;只进不出、只出不进、进不够出&quot;的位置，那里必缺流； ② <strong>说明逐句拆三元组</strong>（起点、终点、名字），与图上对账，剩者即答案，名字抄原词，一句话可能对应两条流； ③ <strong>补实体看&quot;谁&quot;</strong>（人/组织/外部系统，&quot;系统&quot;自己不算）、<strong>补存储看&quot;文件/表/库&quot;</strong>（别拿数据流名冒充存储名）、<strong>补加工名用&quot;动词+名词&quot;</strong>； ④ 数据字典五个记号会默写，能现场写出 <code>XX = A + {B} + (C)</code> 的形式</p><hr>',10))])}const m=a(d,[["render",u]]);export{y as __pageData,m as default};
